module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg x;
    wire z;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply reset
    task apply_reset;
        begin
            areset = 1'b1;
            x = 1'b0;
            #12;
            areset = 1'b0;
            #3;
        end
    endtask

    // Test sequence for 2's complementer
    // 2's complement rule: 
    // - Pass all 0s up to and including the first 1.
    // - Invert all subsequent bits.
    // Example 1: Input stream (LSB first) = 0, 1, 0, 1 (Number = 1010_2 = 10 decimal)
    //   - x=0 -> z=0 (state S0)
    //   - x=1 -> z=1 (state S0 -> S1, first 1 passed as is)
    //   - x=0 -> z=1 (state S1, inverted)
    //   - x=1 -> z=0 (state S1, inverted)
    //   Expected Z sequence: 0, 1, 1, 0 (Value = 0110_2 = 6, wait: 2's comp of 10 is -10. 
    //   Let's trace binary: 1010 (+10) -> invert & add 1: ~1010 + 1 = 0101 + 1 = 0110 (-10). Correct!)

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        // Apply reset test
        apply_reset();

        // Check reset state output
        if (z !== 1'b0) begin
            errors = errors + 1;
        end

        // Test Vector 1: Input 1010 (+10) -> Expected output 0110 (-10)
        // Bit 0: x=0 -> expected z=0
        x = 1'b0; @(posedge clk); #1;
        if (z !== 1'b0) errors = errors + 1;

        // Bit 1: x=1 -> expected z=1
        x = 1'b1; @(posedge clk); #1;
        if (z !== 1'b1) errors = errors + 1;

        // Bit 2: x=0 -> expected z=1
        x = 1'b0; @(posedge clk); #1;
        if (z !== 1'b1) errors = errors + 1;

        // Bit 3: x=1 -> expected z=0
        x = 1'b1; @(posedge clk); #1;
        if (z !== 1'b0) errors = errors + 1;

        // Test Vector 2: Apply reset mid-stream and test another sequence
        // Input 0000 (+0) -> Expected 0000
        apply_reset();

        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;

        // Test Vector 3: Input 0010 (+4) -> Expected 0010 (-4) -> 0010 in binary is 4, 2's comp is -4 (1100)
        apply_reset();

        // Bit 0: x=0 -> z=0
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        // Bit 1: x=0 -> z=0
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b0) errors = errors + 1;
        // Bit 2: x=1 -> z=1 (first 1)
        x = 1'b1; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;
        // Bit 3: x=0 -> z=1 (inverted)
        x = 1'b0; @(posedge clk); #1; if (z !== 1'b1) errors = errors + 1;

        // Final result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
